barcode_template:
{% for item in doc.items -%}
{% set bc = (item.item_code or '')[:13] -%}
{% set nm = (item.item_name or '')[:23] -%}
{% set ra = '%.4f' % (item.rate | float) -%}
{% set rc = '%.4f' % (item.valuation_rate | float if item.valuation_rate else item.rate | float) -%}
^XA
^PW612^LL200
^CI28
^FO5,5^A0N,20,20^FD{{ nm }}^FS
^FO5,30^BY2^BCN,55,N,N,N^FD{{ bc }}^FS
^FO5,95^A0N,16,16^FD{{ bc }}^FS
^FO5,115^A0N,16,16^FDRa:{{ ra }}^FS
^FO5,140^A0N,16,16^FDRc:{{ rc }}^FS
^FO310,5^A0N,20,20^FD{{ nm }}^FS
^FO310,30^BY2^BCN,55,N,N,N^FD{{ bc }}^FS
^FO310,95^A0N,16,16^FD{{ bc }}^FS
^FO310,115^A0N,16,16^FDRa:{{ ra }}^FS
^FO310,140^A0N,16,16^FDRc:{{ rc }}^FS
^XZ
{%- endfor %}
